import{_ as r,o as a,c as e,ag as d}from"./chunks/framework.BjY7aUvS.js";const b=JSON.parse('{"title":"劳动维权 · 被欠薪、被辞退怎么办","description":"劳动维权路径表：欠薪线索反映平台、劳动监察与仲裁（免费、一年时效）、证据清单与常见误区（未签合同反而可主张双倍工资差额）。","frontmatter":{"title":"劳动维权 · 被欠薪、被辞退怎么办","issuer":"人力资源社会保障部 / 依据《劳动合同法》等整理","source_tier":"一级来源","version":"现行政策","published":"—","source_url":"https://www.mohrss.gov.cn/SYrlzyhshbzb/zxhd","status":"现行","tags":["官方查询","劳动维权","欠薪","劳动仲裁","打工人"],"type":"查询页","reviewed":false,"description":"劳动维权路径表：欠薪线索反映平台、劳动监察与仲裁（免费、一年时效）、证据清单与常见误区（未签合同反而可主张双倍工资差额）。"},"headers":[],"relativePath":"query/labor-rights.md","filePath":"query/labor-rights.md"}'),o={name:"query/labor-rights.md"};function s(n,t,h,l,i,g){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="劳动维权-·-被欠薪、被辞退怎么办" tabindex="-1">劳动维权 · 被欠薪、被辞退怎么办 <a class="header-anchor" href="#劳动维权-·-被欠薪、被辞退怎么办" aria-label="Permalink to &quot;劳动维权 · 被欠薪、被辞退怎么办&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待人工校验</p><p>本页由 AI 依据《劳动合同法》等法律与人社部公开政策整理；人社部平台页对自动化访问返回空壳（官方 URL 有效，请人工浏览器打开），程序细节以 12333 与当地经办为准。</p></div><blockquote><p><strong>官方入口</strong>：<a href="https://www.mohrss.gov.cn/SYrlzyhshbzb/zxhd" target="_blank" rel="noreferrer">全国根治欠薪线索反映平台</a>（人社部&quot;政民互动&quot;；另设<strong>国务院客户端</strong>小程序&quot;欠薪线索投诉&quot;）；热线 <strong>12333</strong>；法律援助 <strong>12348</strong>。· 一级来源</p></blockquote><h2 id="速览卡" tabindex="-1">速览卡 <a class="header-anchor" href="#速览卡" aria-label="Permalink to &quot;速览卡&quot;">​</a></h2><p>两条维权主线：<strong>欠薪</strong>（含农民工工资）走&quot;欠薪线索反映平台 + 劳动保障监察&quot;，行政力量介入快；<strong>解雇赔偿等争议</strong>走&quot;劳动仲裁&quot;，不收费、时效一年。先把证据固定好，再按路径走。</p><h2 id="维权路径表" tabindex="-1">维权路径表 <a class="header-anchor" href="#维权路径表" aria-label="Permalink to &quot;维权路径表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>适用</th><th>要点</th></tr></thead><tbody><tr><td>1 · 固定证据</td><td>一切维权的前提</td><td>劳动合同、考勤、工资流水、工牌、工作沟通记录——<strong>缺合同更要留这些</strong></td></tr><tr><td>2 · 协商与调解</td><td>关系未破裂时</td><td>工会/企业调解委员会介入，成本低</td></tr><tr><td>3 · 劳动保障监察投诉</td><td><strong>欠薪、不缴社保</strong>等违法行为</td><td>免费、行政处理快；欠薪线索统一走<a href="https://www.mohrss.gov.cn/SYrlzyhshbzb/zxhd" target="_blank" rel="noreferrer">根治欠薪平台</a>（国务院客户端小程序同名入口）</td></tr><tr><td>4 · 劳动仲裁</td><td>解雇赔偿、合同争议</td><td><strong>不收费</strong>；时效<strong>一年</strong>（自知道权益被侵害起算，《劳动争议调解仲裁法》，待核验）</td></tr><tr><td>5 · 诉讼/支付令</td><td>对仲裁不服或欠薪有凭据</td><td>支付令适用于有明确欠条的情形</td></tr><tr><td>援助</td><td>经济困难/农民工讨薪</td><td><a href="https://am.12348.gov.cn/" target="_blank" rel="noreferrer">12348</a> 法律援助（农民工讨薪有绿色通道，待核验）</td></tr></tbody></table><h2 id="常见误区-逐条纠正" tabindex="-1">常见误区（逐条纠正） <a class="header-anchor" href="#常见误区-逐条纠正" aria-label="Permalink to &quot;常见误区（逐条纠正）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>正确说法</th><th>出处</th></tr></thead><tbody><tr><td>&quot;没签合同，维权没戏&quot;</td><td><strong>未签书面劳动合同</strong>：用人单位应支付二倍工资差额（最多 11 个月，《劳动合同法》第八十二条）——用工记录就是证据</td><td>《劳动合同法》（<a href="https://flk.npc.gov.cn/" target="_blank" rel="noreferrer">全文见国家法律法规数据库</a>）</td></tr><tr><td>&quot;仲裁又贵又慢&quot;</td><td>劳动仲裁<strong>不收费</strong>；多数案件 45 日内审结（待核验）</td><td>《劳动争议调解仲裁法》</td></tr><tr><td>&quot;试用期被辞白辞&quot;</td><td>试用期辞退也要有法定理由，工资不低于本单位相同岗位最低档或约定工资的 80% 且<strong>不低于当地最低工资</strong>（《劳动合同法实施条例》，待核验）</td><td>见<a href="/SageRelay/data/minimum-wage-2026.html">各地最低工资页</a></td></tr><tr><td>&quot;老板跑了只能认栽&quot;</td><td>欠薪线索平台统一转办督办；<strong>拒不支付劳动报酬入刑</strong>（《刑法》第二百七十六条之一，待核验）</td><td>保障农民工工资支付条例（国务院，2020）</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li>工资下限：<a href="/SageRelay/data/minimum-wage-2026.html">各地最低工资</a> · 年度现金事件：<a href="/SageRelay/query/tax-refund.html">个税退税</a></li><li>雇主底细：<a href="/SageRelay/query/enterprise-credit.html">企业信用查询</a> · 纠纷出口：<a href="/SageRelay/query/complaint-channels.html">12315/渠道全景</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>法律</td><td>《劳动合同法》《劳动争议调解仲裁法》《劳动合同法实施条例》（<a href="https://flk.npc.gov.cn/" target="_blank" rel="noreferrer">国家法律法规数据库全文</a>）</td></tr><tr><td>政策</td><td>《保障农民工工资支付条例》（国务院，2020，待核验）</td></tr><tr><td>热线</td><td>12333（劳动保障）· 12348（法律援助）· 12345</td></tr></tbody></table>',13)])])}const c=r(o,[["render",s]]);export{b as __pageData,c as default};
